func matchScaledUnit(value string, units []scaledUnit) (scaledUnit, bool) {
	for _, unit := range units {
		if strings.HasPrefix(value, unit.suffix) {
			return unit, true
		}
	}
	return scaledUnit{}, false
}

func normalizeDecimalTerm(term *decimalTerm) {
	if term.coefficient.Sign() == 0 {
		term.exponent.SetInt64(0)
		return
	}

	text := term.coefficient.Text(10)
	digits := text
	if digits[0] == '-' {
		digits = digits[1:]
	}
	zeros := len(digits) - len(strings.TrimRight(digits, "0"))
	if zeros == 0 {
		return
	}

	term.coefficient.Quo(&term.coefficient, powBigInt(10, int64(zeros)))
	term.exponent.Add(&term.exponent, new(big.Int).SetUint64(uint64(zeros)))
}

func (v exactValue) cmp(other exactValue) int {
	terms := make([]orderedDecimalTerm, 0, len(v.terms)+len(other.terms))
	for i := range v.terms {
		terms = append(terms, newOrderedDecimalTerm(&v.terms[i], false))
	}
	for i := range other.terms {
		terms = append(terms, newOrderedDecimalTerm(&other.terms[i], true))
	}
	return signOfDecimalSum(terms)
}

type orderedDecimalTerm struct {
	term  decimalTerm
	order big.Int
}

func newOrderedDecimalTerm(term *decimalTerm, negate bool) orderedDecimalTerm {
	var result orderedDecimalTerm
	result.term.coefficient.Set(&term.coefficient)
	if negate {
		result.term.coefficient.Neg(&result.term.coefficient)
	}
	result.term.exponent.Set(&term.exponent)
	result.order.Set(decimalOrder(&result.term.exponent, decimalDigits(&result.term.coefficient)))
	return result
}

// signOfDecimalSum computes the sign of a sparse decimal sum. It combines only
// terms close enough in magnitude to affect one another. This means values such
// as 1e100000000000000000000s can be compared exactly without constructing a
// decimal integer with that many zeroes.
func signOfDecimalSum(terms []orderedDecimalTerm) int {
	if len(terms) == 0 {
		return 0
	}

	slices.SortFunc(terms, func(a, b orderedDecimalTerm) int {
		if result := b.order.Cmp(&a.order); result != 0 {
			return result
		}
		return b.term.exponent.Cmp(&a.term.exponent)
	})

	var coefficient, exponent big.Int
	for i := range terms {
		if coefficient.Sign() == 0 {
			coefficient.Set(&terms[i].term.coefficient)
			exponent.Set(&terms[i].term.exponent)
		} else if !addDecimalTerm(&coefficient, &exponent, &terms[i].term) {
			// A shift too large to represent in memory can only occur when the
			// accumulated term dominates all remaining input-sized terms.
			return coefficient.Sign()
		}

		if i == len(terms)-1 {
			return coefficient.Sign()
		}
		if coefficient.Sign() == 0 {
			continue
		}

		currentOrder := decimalOrder(&exponent, decimalDigits(&coefficient))
		currentLowerBound := new(big.Int).Sub(currentOrder, big.NewInt(1))
		remainingUpperBound := new(big.Int).Set(&terms[i+1].order)
		remainingUpperBound.Add(remainingUpperBound, new(big.Int).SetUint64(uint64(ceilLog10(len(terms)-i-1))))
		if currentLowerBound.Cmp(remainingUpperBound) >= 0 {
			return coefficient.Sign()
		}
	}
	return coefficient.Sign()
}

func addDecimalTerm(coefficient, exponent *big.Int, term *decimalTerm) bool {
	switch exponent.Cmp(&term.exponent) {
	case 0:
		coefficient.Add(coefficient, &term.coefficient)
	case 1:
		shift := new(big.Int).Sub(exponent, &term.exponent)
		multiplier, ok := decimalShift(shift)
		if !ok {
			return false
		}
		coefficient.Mul(coefficient, multiplier)
		coefficient.Add(coefficient, &term.coefficient)
		exponent.Set(&term.exponent)
	case -1:
		shift := new(big.Int).Sub(&term.exponent, exponent)
		multiplier, ok := decimalShift(shift)
		if !ok {
			return false
		}
		shiftedTerm := new(big.Int).Mul(&term.coefficient, multiplier)
		coefficient.Add(coefficient, shiftedTerm)
	}

	accumulator := decimalTerm{coefficient: *coefficient, exponent: *exponent}
	normalizeDecimalTerm(&accumulator)
	coefficient.Set(&accumulator.coefficient)
	exponent.Set(&accumulator.exponent)
	return true
}

func decimalShift(shift *big.Int) (*big.Int, bool) {
	if !shift.IsUint64() {
		return nil, false
	}
	n := shift.Uint64()
	maxInt := uint64(^uint(0) >> 1)
	if n > maxInt {
		return nil, false
	}
	return new(big.Int).Exp(big.NewInt(10), new(big.Int).SetUint64(n), nil), true
}

func decimalDigits(value *big.Int) int {
	if value.Sign() < 0 {
		return len(value.Text(10)) - 1
	}
	return len(value.Text(10))
}

func ceilLog10(value int) int {
	if value <= 1 {
		return 0
	}
	power, result := 1, 0
	for power < value {
		if power > int(^uint(0)>>1)/10 {
			return result + 1
		}
		power *= 10
		result++
	}
	return result
}

type semanticVersion struct {
	core       [3]string
	prerelease []string
}

func parseSemanticVersion(value string) (semanticVersion, bool) {
	var version semanticVersion
	if strings.HasPrefix(value, "v") {
		value = value[1:]
	}
	if value == "" {
		return version, false
	}

	withoutBuild := value
	if plus := strings.IndexByte(withoutBuild, '+'); plus >= 0 {
		build := withoutBuild[plus+1:]
		withoutBuild = withoutBuild[:plus]
		if !validSemverIdentifiers(build, false) {
			return version, false
		}
	}

	core := withoutBuild
	if dash := strings.IndexByte(core, '-'); dash >= 0 {
		prerelease := core[dash+1:]
		core = core[:dash]
		if !validSemverIdentifiers(prerelease, true) {
			return version, false
		}
		version.prerelease = strings.Split(prerelease, ".")
	}

	parts := strings.Split(core, ".")
	if len(parts) != len(version.core) {
		return semanticVersion{}, false
	}
	for i, part := range parts {
		if !validSemverNumber(part) {
			return semanticVersion{}, false
		}
		version.core[i] = part
	}
	return version, true
}

func validSemverNumber(value string) bool {
	if value == "" || len(value) > 1 && value[0] == '0' {
		return false
	}
	for i := range value {
		if !isASCIIDigit(value[i]) {
			return false
		}
	}
	return true
}

func validSemverIdentifiers(value string, prerelease bool) bool {
	if value == "" {
		return false
	}
	for _, identifier := range strings.Split(value, ".") {
		if identifier == "" {
			return false
		}
		numeric := true
		for i := range identifier {
			c := identifier[i]
			if !isASCIIDigit(c) {
				numeric = false
			}
			if !isASCIIDigit(c) && !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && c != '-' {
				return false
			}
		}
		if prerelease && numeric && len(identifier) > 1 && identifier[0] == '0' {
			return false
		}
	}
	return true
}

func (v semanticVersion) cmp(other semanticVersion) int {
	for i := range v.core {
		if result := compareUnsignedDecimalStrings(v.core[i], other.core[i]); result != 0 {
			return result
		}
	}

	if len(v.prerelease) == 0 || len(other.prerelease) == 0 {
		switch {
		case len(v.prerelease) == 0 && len(other.prerelease) == 0:
			return 0
		case len(v.prerelease) == 0:
			return 1
		default:
			return -1
		}
	}

	common := min(len(v.prerelease), len(other.prerelease))
	for i := 0; i < common; i++ {
		a, b := v.prerelease[i], other.prerelease[i]
		aNumeric, bNumeric := allASCIIDigits(a), allASCIIDigits(b)
		switch {
		case aNumeric && bNumeric:
			if result := compareUnsignedDecimalStrings(a, b); result != 0 {
				return result
			}
		case aNumeric:
			return -1
		case bNumeric:
			return 1
		default:
			if result := strings.Compare(a, b); result != 0 {
				return result
			}
		}
	}
	return cmp.Compare(len(v.prerelease), len(other.prerelease))
}

func compareUnsignedDecimalStrings(a, b string) int {
	if len(a) != len(b) {
		return cmp.Compare(len(a), len(b))
	}
	return strings.Compare(a, b)
}

func allASCIIDigits(value string) bool {
	if value == "" {
		return false
	}
	for i := range value {
		if !isASCIIDigit(value[i]) {
			return false
		}
	}
	return true
}

func compareAddresses(a, b netip.Addr) int {
	if a.Is4() != b.Is4() {
		if a.Is4() {
			return -1
		}
		return 1
	}

	var result int
	if a.Is4() {
		aa, bb := a.As4(), b.As4()
		result = bytes.Compare(aa[:], bb[:])
	} else {
		aa, bb := a.As16(), b.As16()
		result = bytes.Compare(aa[:], bb[:])
	}
	if result != 0 {
		return result
	}
	return strings.Compare(a.Zone(), b.Zone())
}

func comparePrefixes(a, b netip.Prefix) int {
	if result := compareAddresses(a.Addr(), b.Addr()); result != 0 {
		return result
	}
	return cmp.Compare(a.Bits(), b.Bits())
}

// compareNatural compares digit runs by their arbitrary-size integer value and
// all other bytes lexically. Naturally equivalent spellings receive a lexical
// tie-break, making the result a total order (unlike facette/natsort, which can
// report both a < b and b < a for equivalent digit runs).
func compareNatural(a, b string) int {
	ai, bi := 0, 0
	for ai < len(a) && bi < len(b) {
		if isASCIIDigit(a[ai]) && isASCIIDigit(b[bi]) {
			aEnd, bEnd := ai, bi
			for aEnd < len(a) && isASCIIDigit(a[aEnd]) {
				aEnd++
			}
			for bEnd < len(b) && isASCIIDigit(b[bEnd]) {
				bEnd++
			}

			aSignificant, bSignificant := ai, bi
			for aSignificant < aEnd && a[aSignificant] == '0' {
				aSignificant++
			}
			for bSignificant < bEnd && b[bSignificant] == '0' {
				bSignificant++
			}
			if aDigits, bDigits := aEnd-aSignificant, bEnd-bSignificant; aDigits != bDigits {
				return cmp.Compare(aDigits, bDigits)
			}
			if result := strings.Compare(a[aSignificant:aEnd], b[bSignificant:bEnd]); result != 0 {
				return result
			}
			ai, bi = aEnd, bEnd
			continue
		}

		if a[ai] != b[bi] {
			return cmp.Compare(a[ai], b[bi])
		}
		ai++
		bi++
	}
	if ai != len(a) || bi != len(b) {
		return cmp.Compare(len(a)-ai, len(b)-bi)
	}
	return strings.Compare(a, b)
}

func isASCIIDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

"""wazoobench naive baseline: the both-ways check on the swapped tasks.

For each swapped task (t0188, t0611) it builds two workdirs from the stored
verifier assets and runs the contract checks against both:

- INFORMED: the recorded PASS solution (t0188: the recorded
  promql/labelsort.go recovered verbatim from the trajectory; t0611: the
  PASS run's cache implementation replayed against the pinned base commit).
- NAIVE: a hand-written no-memory variant (t0188: natural-sort-only
  comparator, the behavior the issue replaces; t0611: CLI flags accepted but
  no actual caching).

The verifier discriminates when naive fails at least one grading check while
informed passes all of them. Any check that CANNOT discriminate is flagged
in the report (and in the spec), never faked.

Zero API spend: this script never calls the model.

Usage: python3 src/naive_baseline.py [--keep-workdirs]
"""

from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
ASSETS = ROOT / "src" / "verifier-assets"
GO = "/usr/local/go/bin/go" if Path("/usr/local/go/bin/go").exists() else shutil.which("go")

VULTURE_BASE = "ef9e6de"  # just before the 2.15 release bump (see the t0611 spec)


def run(cmd: list[str], cwd: str | None = None, env: dict | None = None) -> tuple[int, str]:
    proc = subprocess.run(cmd, capture_output=True, text=True, cwd=cwd, env=env)
    return proc.returncode, (proc.stdout + proc.stderr)


def check_t0188(workdirs: dict[str, Path]) -> dict:
    """Contract: go test ./... with the authored contract test injected."""
    report: dict = {"task": "t0188", "grader": "go test ./... (authored contract test)"}
    for label, workdir in workdirs.items():
        shutil.copy(ASSETS / "t0188-labelsort-contract/labelsort_contract_test.go", workdir / "labelsort_contract_test.go")
        code, output = run([GO, "test", "./..."], cwd=str(workdir))
        failures = [line.split()[2].rstrip("()") for line in output.splitlines() if line.startswith("--- FAIL")]
        report[label] = {"exit_code": code, "pass": code == 0, "failing_checks": failures, "output_tail": output[-400:]}
    return report


def check_t0611(workdirs: dict[str, Path]) -> dict:
    """Contract: the authored stdlib check script (11 checks)."""
    report: dict = {"task": "t0611", "grader": "verifier-check.py (authored contract script)"}
    script = ASSETS / "t0611-cache-contract/verifier-check.py"
    for label, workdir in workdirs.items():
        target = workdir / "t0611-cache-contract"
        if not target.exists():
            shutil.copytree(script.parent, target)
        code, output = run([sys.executable, "t0611-cache-contract/verifier-check.py"], cwd=str(workdir))
        fails = [line[5:].split(":")[0].strip() for line in output.splitlines() if line.startswith("FAIL ")]
        if code != 0 and not fails:
            # e.g. the naive variant has no cache module at all: the script
            # exits on the import itself, which fails every contract check
            tail = [line for line in output.splitlines() if line.strip()][-1:]
            fails = [f"<script aborted: {tail[0][:160] if tail else 'no output'}>"]
        report[label] = {"exit_code": code, "pass": code == 0, "failing_checks": fails, "output_tail": output[-400:]}
    return report


def build_t0188_workdirs(base: Path) -> dict[str, Path]:
    workdirs = {}
    for label in ("informed", "naive"):
        d = base / f"t0188-{label}"
        shutil.copytree(ASSETS / f"t0188-labelsort-{label}", d)
        workdirs[label] = d
    return workdirs


def build_t0611_workdirs(base: Path) -> dict[str, Path]:
    workdirs = {}
    for label in ("informed", "naive"):
        d = base / f"t0611-{label}"
        d.mkdir(parents=True, exist_ok=True)
        # clone from the mirror at the pinned base commit
        code, output = run(["git", "clone", "--filter=blob:none", "https://github.com/jendrikseipp/vulture", "."], cwd=str(d))
        if code != 0:
            raise RuntimeError(f"vulture clone failed: {output[-500:]}")
        code, output = run(["git", "checkout", VULTURE_BASE], cwd=str(d))
        if code != 0:
            raise RuntimeError(f"checkout {VULTURE_BASE} failed: {output[-500:]}")
        patch = ASSETS / f"t0611-cache-{label}/{'informed' if label == 'informed' else 'naive'}-solution.patch"
        code, output = run(["git", "apply", str(patch)], cwd=str(d))
        if code != 0:
            raise RuntimeError(f"{label} patch failed: {output[-500:]}")
        code, output = run([sys.executable, "-m", "pip", "install", "-q", "--no-build-isolation", "--break-system-packages", "-e", "."], cwd=str(d))
        if code != 0:
            raise RuntimeError(f"pip install -e failed for {label}: {output[-500:]}")
        workdirs[label] = d
    return workdirs


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--keep-workdirs", action="store_true")
    args = parser.parse_args(argv)

    reports = []
    if args.keep_workdirs:
        base = _fresh_dir(Path(tempfile.gettempdir()) / "wazoobench-naive-baseline")
    else:
        base = Path(tempfile.mkdtemp(prefix="wazoobench-naive-"))

    t0188 = check_t0188(build_t0188_workdirs(base))
    discriminated = t0188["informed"]["pass"] and not t0188["naive"]["pass"]
    t0188["discriminates"] = discriminated
    if not discriminated:
        t0188["flag"] = "informed must pass and naive must fail; a check that both pass cannot discriminate"
    reports.append(t0188)
    print(f"t0188: informed pass={t0188['informed']['pass']} naive pass={t0188['naive']['pass']} "
          f"(naive fails: {t0188['naive']['failing_checks']})")

    t0611 = check_t0611(build_t0611_workdirs(base))
    discriminated = t0611["informed"]["pass"] and not t0611["naive"]["pass"]
    t0611["discriminates"] = discriminated
    if not discriminated:
        t0611["flag"] = "informed must pass and naive must fail; a check that both pass cannot discriminate"
    reports.append(t0611)
    print(f"t0611: informed pass={t0611['informed']['pass']} naive pass={t0611['naive']['pass']} "
          f"(naive fails: {t0611['naive']['failing_checks']})")

    out = ROOT / "docs" / "naive-baseline-report.json"
    out.write_text(json.dumps(reports, indent=2))
    print(f"wrote {out}")

    ok = all(r["discriminates"] for r in reports)
    return 0 if ok else 1


def _fresh_dir(path: Path) -> Path:
    if path.exists():
        shutil.rmtree(path)
    path.mkdir(parents=True)
    return path


