 58	// compareLabelValues compares label values in the human-oriented order used by
 59	// sort_by_label. It always returns a strict three-way result: typed values that
 60	// represent the same value are ordered naturally by their original spelling.
 61	func compareLabelValues(a, b string) int {
 62		if a == b {
 63			return 0
 64		}
 65	
 66		pa := parseLabelValue(a)
 67		pb := parseLabelValue(b)
 68		if pa.kind != pb.kind {
 69			return cmp.Compare(pa.kind, pb.kind)
 70		}
 71	
 72		var result int
 73		switch pa.kind {
 74		case labelValueNumber:
 75			result = pa.number.cmp(pb.number)
 76		case labelValueDuration, labelValueBytes:
 77			result = pa.magnitude.cmp(pb.magnitude)
 78		case labelValueSemver:
 79			result = pa.version.cmp(pb.version)
 80		case labelValueIP:
 81			result = compareAddresses(pa.address, pb.address)
 82		case labelValueCIDR:
 83			result = comparePrefixes(pa.prefix, pb.prefix)
 84		case labelValueTimestamp:
 85			result = pa.timestamp.Compare(pb.timestamp)
 86		}
 87		if result != 0 {
 88			return result
 89		}
 90	
 91		return compareNatural(a, b)
 92	}
 93	
 94	func parseLabelValue(value string) parsedLabelValue {
 95		if hasLeadingWhitespace(value) {
 96			return parsedLabelValue{kind: labelValueLeadingWhitespace}
 97		}
 98	
 99		if sign, ok := parseInfinity(value); ok {
100			if sign > 0 {
101				return parsedLabelValue{kind: labelValuePositiveInfinity}
102			}
103			return parsedLabelValue{kind: labelValueNegativeInfinity}
104		}
105	
106		if number, ok := parseExactDecimal(value); ok {
107			return parsedLabelValue{kind: labelValueNumber, number: number}
108		}
109		if duration, ok := parseScaledValue(value, durationUnits); ok {
110			return parsedLabelValue{kind: labelValueDuration, magnitude: duration}
111		}
112		if byteCount, ok := parseScaledValue(value, byteUnits); ok {
113			return parsedLabelValue{kind: labelValueBytes, magnitude: byteCount}
114		}
115		if version, ok := parseSemanticVersion(value); ok {
116			return parsedLabelValue{kind: labelValueSemver, version: version}
117		}
118		if address, err := netip.ParseAddr(value); err == nil {
119			return parsedLabelValue{kind: labelValueIP, address: address}
120		}
121		if prefix, err := netip.ParsePrefix(value); err == nil {
122			return parsedLabelValue{kind: labelValueCIDR, prefix: prefix.Masked()}
123		}
124		if timestamp, err := time.Parse(time.RFC3339Nano, value); err == nil {
125			return parsedLabelValue{kind: labelValueTimestamp, timestamp: timestamp}
126		}
127		return parsedLabelValue{kind: labelValueNatural}
128	}
