138	func parseInfinity(value string) (int, bool) {
139		switch strings.ToLower(value) {
140		case "inf", "+inf", "infinity", "+infinity":
141			return 1, true
142		case "-inf", "-infinity":
143			return -1, true
144		default:
145			return 0, false
146		}
147	}
