149	// exactDecimal represents coefficient * 10^exponent. The coefficient is kept
150	// as canonical decimal digits so both it and the exponent can be arbitrarily
151	// large without converting through a floating-point type.
152	type exactDecimal struct {
153		sign        int
154		coefficient string
155		exponent    big.Int
156	}
