163	func parseExactDecimalPrefix(value string, start int) (exactDecimal, int, bool) {
164		var number exactDecimal
165		if start >= len(value) {
166			return number, start, false
167		}
168	
169		i := start
170		sign := 1
171		if value[i] == '+' || value[i] == '-' {
172			if value[i] == '-' {
173				sign = -1
174			}
175			i++
176			if i == len(value) {
177				return number, start, false
178			}
179		}
180	
181		integerStart := i
182		for i < len(value) && isASCIIDigit(value[i]) {
183			i++
184		}
185		integerEnd := i
186	
187		fractionStart, fractionEnd := i, i
188		if i < len(value) && value[i] == '.' {
189			i++
190			fractionStart = i
191			for i < len(value) && isASCIIDigit(value[i]) {
192				i++
193			}
194			fractionEnd = i
195		}
196		if integerStart == integerEnd && fractionStart == fractionEnd {
197			return number, start, false
198		}
199	
200		var parsedExponent big.Int
201		if i < len(value) && (value[i] == 'e' || value[i] == 'E') {
202			exponentMarker := i
203			j := i + 1
204			if j < len(value) && (value[j] == '+' || value[j] == '-') {
205				j++
206			}
207			exponentDigits := j
208			for j < len(value) && isASCIIDigit(value[j]) {
209				j++
210			}
211			// An E can also begin a byte unit (EB or EiB). Only consume it as
212			// an exponent when at least one exponent digit follows it.
213			if j > exponentDigits {
214				exponentText := value[exponentMarker+1 : j]
215				if _, ok := parsedExponent.SetString(exponentText, 10); !ok {
216					return number, start, false
217				}
218				i = j
219			}
220		}

220		}
221	
222		digits := value[integerStart:integerEnd] + value[fractionStart:fractionEnd]
223		digits = strings.TrimLeft(digits, "0")
224		if digits == "" {
225			return exactDecimal{}, i, true
226		}
227	
228		trailingZeros := len(digits) - len(strings.TrimRight(digits, "0"))
229		digits = digits[:len(digits)-trailingZeros]
230	
231		number.sign = sign
232		number.coefficient = digits
233		number.exponent.Set(&parsedExponent)
234		number.exponent.Sub(&number.exponent, new(big.Int).SetUint64(uint64(fractionEnd-fractionStart)))
235		number.exponent.Add(&number.exponent, new(big.Int).SetUint64(uint64(trailingZeros)))
236		return number, i, true
237	}
