239	func (d exactDecimal) cmp(other exactDecimal) int {
240		if d.sign != other.sign {
241			return cmp.Compare(d.sign, other.sign)
242		}
243		if d.sign == 0 {
244			return 0
245		}
246	
247		result := d.cmpAbs(other)
248		if d.sign < 0 {
249			return -result
250		}
251		return result
252	}
253	
254	func (d exactDecimal) cmpAbs(other exactDecimal) int {
255		dOrder := decimalOrder(&d.exponent, len(d.coefficient))
256		otherOrder := decimalOrder(&other.exponent, len(other.coefficient))
257		if result := dOrder.Cmp(otherOrder); result != 0 {
258			return result
259		}
260	
261		maxDigits := max(len(d.coefficient), len(other.coefficient))
262		for i := 0; i < maxDigits; i++ {
263			dDigit, otherDigit := byte('0'), byte('0')
264			if i < len(d.coefficient) {
265				dDigit = d.coefficient[i]
266			}
267			if i < len(other.coefficient) {
268				otherDigit = other.coefficient[i]
269			}
270			if dDigit != otherDigit {
271				return cmp.Compare(dDigit, otherDigit)
272			}
273		}
274		return 0
275	}
