334	// parseScaledValue parses a sequence such as 1h30m or 1GiB512MiB. A leading
335	// sign applies to the complete sequence, matching time.Duration and the byte
336	// parser previously used by Prometheus. Every coefficient accepts the exact
337	// decimal/scientific grammar used for plain numbers.
338	func parseScaledValue(value string, units []scaledUnit) (exactValue, bool) {
339		var parsed exactValue
340		if value == "" {
341			return parsed, false
342		}
343	
344		i := 0
345		sign := 1
346		if value[i] == '+' || value[i] == '-' {
347			if value[i] == '-' {
348				sign = -1
349			}
350			i++
351			if i == len(value) {
352				return parsed, false
353			}
354		}
355	
356		for i < len(value) {
357			coefficient, end, ok := parseExactDecimalPrefix(value, i)
358			if !ok || coefficient.sign < 0 || end == i {
359				return exactValue{}, false
360			}
361	
362			unit, ok := matchScaledUnit(value[end:], units)
363			if !ok {
364				return exactValue{}, false
365			}
366			i = end + len(unit.suffix)
367	
368			if coefficient.sign == 0 {
369				continue
370			}
371			var term decimalTerm
372			term.coefficient.SetString(coefficient.coefficient, 10)
373			term.coefficient.Mul(&term.coefficient, unit.factor)
374			if sign < 0 {
375				term.coefficient.Neg(&term.coefficient)
376			}
377			term.exponent.Set(&coefficient.exponent)
378			normalizeDecimalTerm(&term)
379			parsed.terms = append(parsed.terms, term)
380		}
381	
382		return parsed, true
383	}
