		ba := CompareLabelValues(p[1], p[0])
		if ab >= 0 || ba <= 0 {
			t.Errorf("expected %q < %q, got %d/%d", p[0], p[1], ab, ba)
		}
	}
}

func TestExtraTotalOrder(t *testing.T) {
	values := []string{
		"", " ", "  ", "\t9", " z", "0", "-0", "+0", "0.0", "0e10",
		"1", "01", "001", "+1", "-1", "1.0", "1e0", "1e+0", "1E-3",
		"1e", "1e+", "1e-", "e1", ".5", "1.", "-.5", "+.5",
		"NaN", "nan", "Inf", "+Inf", "-Inf", "Infinity", "-Infinity",
		"1ns", "1us", "1µs", "1μs", "1ms", "1s", "1m", "1h", "1d", "1w", "1y",
		"1h30m", "-1h30m", "1.5e3ms", "1e3ms", "1e1000000000000000000s",
		"1B", "1KB", "1KiB", "1MB", "1MiB", "1EB", "1EiB", "1YB", "1YiB",
		"1e3B", "1e1000000000000000000B",
		"v1.2.3", "1.2.3", "v1.2.3-alpha", "v1.2.3-alpha.1", "v1.2.3+build",
		"1.2.3.4", "v1", "v1.2", "1.2.3.4.5", "1.2.03",
		"1.2.3.4", "::1", "::ffff:1.2.3.4", "2001:db8::1", "fe80::1%eth0",
		"10.0.0.0/8", "10.0.0.0/16", "10.0.0.0/24", "1.2.3.4/32", "::/0", "::1/128",
		"2024-01-02T00:00:00Z", "2024-01-02T00:00:00+01:00", "2024-01-02T00:00:00.5Z",
		"abc", "ABC", "a1b2", "a01b002", "0x10", "1e", "NaN",
	}
	for _, a := range values {
		if CompareLabelValues(a, a) != 0 {
			t.Errorf("self compare nonzero: %q", a)
		}
		for _, b := range values {
			ab, ba := CompareLabelValues(a, b), CompareLabelValues(b, a)
			if (ab < 0) != (ba > 0) || (ab > 0) != (ba < 0) || (ab == 0) != (ba == 0) {
				t.Errorf("antisymmetry %q/%q: %d/%d", a, b, ab, ba)
			}
			if a != b && ab == 0 {
				t.Errorf("distinct values compare equal: %q %q", a, b)
			}
			for _, c := range values {
				bc, ac := CompareLabelValues(b, c), CompareLabelValues(a, c)
				if ab <= 0 && bc <= 0 && ac > 0 {
					t.Errorf("transitivity %q <= %q <= %q but %q > %q", a, b, c, a, c)
				}
			}
		}
	}
}

func TestExtraRandomTotalOrder(t *testing.T) {
	r := rand.New(rand.NewSource(1))
	alphabet := []byte("0123456789.+-eE vV/:%abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\t")
	random := func() string {
		n := r.Intn(20)
		b := make([]byte, n)
		for i := range b {
			b[i] = alphabet[r.Intn(len(alphabet))]
		}
		return string(b)
	}
	values := make([]string, 2000)
	for i := range values {
		values[i] = random()
	}
	sorted := append([]string(nil), values...)
	sort.Slice(sorted, func(i, j int) bool { return CompareLabelValues(sorted[i], sorted[j]) < 0 })
	for i := 0; i+1 < len(sorted); i++ {
		if CompareLabelValues(sorted[i], sorted[i+1]) > 0 {
			t.Fatalf("bad sort at %d: %q %q", i, sorted[i], sorted[i+1])
		}
	}
	// all pair antisymmetry/transitivity sampled
	for i := 0; i < len(values); i++ {
		for j := 0; j < 200; j++ {
			k := r.Intn(len(values))
			a, b, c := values[i], values[r.Intn(len(values))], values[k]
			ab, ba := CompareLabelValues(a, b), CompareLabelValues(b, a)
			if (ab < 0) != (ba > 0) || (ab > 0) != (ba < 0) {
				t.Fatalf("antisymmetry %q/%q: %d/%d", a, b, ab, ba)
			}
			bc, ac := CompareLabelValues(b, c), CompareLabelValues(a, c)
			if ab <= 0 && bc <= 0 && ac > 0 {
				fmt.Println("transitivity failure", a, b, c)
				t.Fatalf("transitivity %q <= %q <= %q but result %d", a, b, c, ac)
			}
		}
	}
}
