import type { Relation } from '../relation/types';
import { isRelation } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import type { TraitRegistry, TraitRegistryEntry } from './types';

export type TraitRegistryMaps = {
    traitKeys: Map<Trait, string>;
    relationKeys: Map<Relation, string>;
};

export function createTraitRegistry(
    ...entries: readonly (readonly [string, TraitRegistryEntry])[]
): TraitRegistry {
    const registry = new Map<string, TraitRegistryEntry>();
    const traits = new Set<Trait>();
    const relations = new Set<Relation>();

    for (const [key, entry] of entries) {
        if (registry.has(key)) {
            throw new Error(`Koota: Duplicate trait registry key "${key}".`);
        }

        if (isRelation(entry)) {
            if (relations.has(entry)) {
                throw new Error(`Koota: Relation registered more than once under key "${key}".`);
            }
            relations.add(entry);
        } else {
            if (traits.has(entry)) {
                throw new Error(`Koota: Trait registered more than once under key "${key}".`);
            }
            traits.add(entry);
        }

        registry.set(key, entry);
    }

    return registry;
}

export function getTraitRegistryMaps(registry: TraitRegistry): TraitRegistryMaps {
    if (!registry || typeof registry.get !== 'function') {
        throw new Error('Koota: Invalid trait registry.');
    }

    const traitKeys = new Map<Trait, string>();
    const relationKeys = new Map<Relation, string>();

    for (const [key, entry] of registry) {
        if (isRelation(entry)) relationKeys.set(entry, key);
        else traitKeys.set(entry, key);
    }

    return { traitKeys, relationKeys };
}
