	})

	t.Run("no match returns None", func(t *testing.T) {
		res, err := callBuiltin(
			t, memberQueryOne, doc, starlark.String("$.missing"))
		require.NoError(t, err)
		assert.Equal(t, starlark.None, res)
	})
