            return found

        def add_name(name, bases):
            parts = [part for part in name.split(".") if part]
            if not parts:
                return

            # Importing a submodule executes package __init__.py files too.
            for index in range(1, len(parts) + 1):
                relative = Path(*parts[:index])
                for base in bases:
                    if add_candidate(base / relative):
                        break

            # As a fallback, resolve a unique matching suffix.  This supports
            # scans rooted inside a package without linking unrelated modules
            # which happen to have the same basename.
            final_parts = parts[:-1] + [parts[-1] + ".py"]
            init_parts = parts + ["__init__.py"]
            matches = [
                key
                for key, module_path in module_paths.items()
                if tuple(module_path.parts[-len(final_parts) :])
                == tuple(final_parts)
                or tuple(module_path.parts[-len(init_parts) :])
                == tuple(init_parts)
            ]
            if len(matches) == 1:
                dependencies.add(matches[0])

        absolute_bases = [importer.parent, *search_roots]
        for import_spec in import_specs:
            if import_spec["kind"] == "import":
                add_name(import_spec["name"], absolute_bases)
                continue

            module = import_spec["module"]
            level = import_spec["level"]
            names = [name for name in import_spec["names"] if name != "*"]
            if level:
                relative_base = importer.parent
                for _ in range(level - 1):
                    relative_base = relative_base.parent
                bases = [relative_base]
                if module:
                    add_name(module, bases)
                    for name in names:
                        add_name(f"{module}.{name}", bases)
                else:
                    for name in names:
                        add_name(name, bases)
            else:
                add_name(module, absolute_bases)
                for name in names:
                    add_name(f"{module}.{name}", absolute_bases)

