    @staticmethod
    def _whitelist_info(import_name):
        # Import aliases are identifiers.  Rejecting other strings also keeps
        # a malformed cache from turning into a package-data path traversal.
        if not import_name.isidentifier():
            return None
        relative_path = Path("whitelists") / f"{import_name}_whitelist.py"
        try:
            module_data = pkgutil.get_data("vulture", str(relative_path))
        except OSError:
